-- Item master imported from the company stock list.
-- Codes are ours: category prefix + running number.
-- 2607 items. 16 rows in the sheet were the same item listed twice
-- (identical names, different codes); their makes were merged onto one item.

SET FOREIGN_KEY_CHECKS = 0;

ON DUPLICATE KEY UPDATE name=VALUES(name);

ON DUPLICATE KEY UPDATE name=VALUES(name);

ON DUPLICATE KEY UPDATE name=VALUES(name);

ON DUPLICATE KEY UPDATE name=VALUES(name);


SELECT c.code, COALESCE(MAX(CAST(SUBSTRING_INDEX(i.code,'-',-1) AS UNSIGNED)),0)
  FROM item_categories c LEFT JOIN items i ON i.category_id=c.id
 GROUP BY c.code
ON DUPLICATE KEY UPDATE last_no=VALUES(last_no);

SET FOREIGN_KEY_CHECKS = 1;